L15_1 = "\227\129\160\227\129\163\227\129\159\227\130\137\227\130\170\227\131\172\227\129\171\227\130\130\228\187\149\228\186\139\227\130\146\227\129\143\227\130\140\227\128\130\230\137\139\228\188\157\227\129\163\227\129\166\227\130\132\227\130\139\227\129\139\227\130\137\227\128\130"
L14_1.m_Talk_JPN = L15_1
