L14_1.m_Talk_TWN = L15_1
L15_1 = "\224\184\154\224\184\173\224\184\129\224\184\161\224\184\178\224\185\128\224\184\165\224\184\162\224\184\167\224\185\136\224\184\178\224\184\149\224\185\137\224\184\173\224\184\135\224\184\151\224\184\179\224\184\173\224\184\176\224\185\132\224\184\163 \224\184\156\224\184\161\224\184\136\224\184\176\224\184\138\224\185\136\224\184\167\224\184\162"
