L14_1.m_Talk_VTN = L15_1
L15_1 = "\229\166\130\230\158\156\230\152\175\232\191\153\230\160\183\239\188\140\229\145\138\232\175\137\230\136\145\232\175\165\229\129\154\228\187\128\228\185\136\229\144\167\227\128\130\230\136\145\230\132\191\230\132\143\229\184\174\228\189\160\227\128\130"
