L18_1 = "\236\152\164\237\149\180\235\138\148 \237\149\152\236\167\128 \235\167\136. \235\130\180 \236\185\156\234\181\172\235\165\188 \236\156\132\237\151\152\237\149\156 \236\157\188\236\151\144 \235\129\140\236\150\180\235\147\164\236\157\180\235\138\148 \234\177\180 \235\167\136\236\157\140\236\151\144 \236\149\136 \235\147\164\236\150\180."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "\232\170\164\232\167\163\227\129\153\227\130\139\227\129\170\227\130\136\227\128\130\227\130\170\227\131\172\227\129\174\229\143\139\227\130\146\229\141\177\233\153\186\227\129\170\227\129\147\227\129\168\227\129\171\229\188\149\227\129\141\229\133\165\227\130\140\227\130\139\227\129\174\227\129\175\230\176\151\227\129\171\229\133\165\227\130\137\227\129\170\227\129\132\227\128\130"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Don\226\128\153t get me wrong. I don\226\128\153t like you dragging my friend into this dangerous business."
L17_1.m_Talk_ENG = L18_1
L18_1 = "\228\189\160\228\184\141\232\166\129\232\170\164\230\156\131\239\188\140\230\136\145\228\184\141\229\150\156\230\173\161\228\189\160\230\138\138\230\136\145\230\156\139\229\143\139\230\139\150\228\184\139\230\176\180\227\128\130"
L17_1.m_Talk_TWN = L18_1
L18_1 = "\224\184\173\224\184\162\224\185\136\224\184\178\224\185\128\224\184\130\224\185\137\224\184\178\224\185\131\224\184\136\224\184\156\224\184\180\224\184\148\224\184\165\224\185\136\224\184\176 \224\184\156\224\184\161\224\185\132\224\184\161\224\185\136\224\184\138\224\184\173\224\184\154\224\184\171\224\184\163\224\184\173\224\184\129\224\184\153\224\184\176\224\184\151\224\184\181\224\185\136\224\185\128\224\184\152\224\184\173\224\184\161\224\184\178\224\184\165\224\184\178\224\184\129\224\185\128\224\184\158\224\184\183\224\185\136\224\184\173\224\184\153\224\184\156\224\184\161\224\185\132\224\184\155\224\184\151\224\184\179\224\184\173\224\184\176\224\185\132\224\184\163\224\184\173\224\184\177\224\184\153\224\184\149\224\184\163\224\184\178\224\184\162"
L17_1.m_Talk_THA = L18_1
L18_1 = "\196\144\225\187\171ng hi\225\187\131u sai \195\189 t\195\180i. T\195\180i kh\195\180ng th\195\173ch c\195\180 l\195\180i k\195\169o b\225\186\161n t\195\180i v\195\160o c\195\180ng vi\225\187\135c nguy hi\225\187\131m n\195\160y."
L17_1.m_Talk_VTN = L18_1
L18_1 = "\229\136\171\232\175\175\228\188\154\227\128\130\230\136\145\232\174\168\229\142\140\228\189\160\230\138\138\230\136\145\231\154\132\230\156\139\229\143\139\229\141\183\229\133\165\229\141\177\233\153\169\231\154\132\228\186\139\230\131\133\227\128\130"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Versteh mich nicht falsch. Ich mag es nicht, wenn du meinen Freund in dieses gef\195\164hrliche Gesch\195\164ft hineinziehst."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oui, mais que ce soit clair : \195\167a ne me pla\195\174t pas que tu entra\195\174nes mon ami dans une affaire aussi dangereuse."
L17_1.m_Talk_FRA = L18_1
