L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "\227\129\160\227\129\140\227\128\129\227\130\170\227\131\172\227\129\175\230\185\138\227\130\146\228\191\161\227\129\152\227\129\166\227\130\139\227\128\130\227\129\160\227\129\139\227\130\137\230\185\138\227\129\140\228\191\161\227\129\152\227\130\139\227\129\138\229\137\141\227\129\171\229\141\148\229\138\155\227\129\153\227\130\139\227\129\160\227\129\145\227\129\160\227\128\130"
L18_1.m_Talk_JPN = L19_1
L19_1 = "But I believe in Minato, and I will help you only because Minato believes in you."
L18_1.m_Talk_ENG = L19_1
L19_1 = "\228\189\134\230\152\175\230\136\145\231\155\184\228\191\161\229\141\151\232\163\149\229\164\143\227\128\130\229\155\160\231\130\186\229\141\151\232\163\149\229\164\143\231\155\184\228\191\161\228\189\160\239\188\140\230\137\128\228\187\165\230\136\145\230\137\141\229\185\171\228\189\160\231\154\132\227\128\130"
L18_1.m_Talk_TWN = L19_1
L19_1 = "\224\185\129\224\184\149\224\185\136\224\184\156\224\184\161\224\185\128\224\184\138\224\184\183\224\185\136\224\184\173\224\185\131\224\184\153\224\184\149\224\184\177\224\184\167\224\184\161\224\184\180\224\184\153\224\184\178\224\185\130\224\184\149\224\184\176 \224\185\129\224\184\165\224\184\176\224\184\151\224\184\181\224\185\136\224\184\156\224\184\161\224\184\136\224\184\176\224\184\138\224\185\136\224\184\167\224\184\162\224\185\128\224\184\152\224\184\173\224\184\129\224\185\135\224\185\128\224\184\158\224\184\163\224\184\178\224\184\176\224\184\161\224\184\180\224\184\153\224\184\178\224\185\130\224\184\149\224\184\176\224\185\128\224\184\138\224\184\183\224\185\136\224\184\173\224\185\131\224\184\153\224\184\149\224\184\177\224\184\167\224\185\128\224\184\152\224\184\173\224\185\128\224\184\151\224\185\136\224\184\178\224\184\153\224\184\177\224\185\137\224\184\153"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nh\198\176ng t\195\180i tin Minato, v\195\160 t\195\180i s\225\186\189 gi\195\186p c\195\180 ch\225\187\137 v\195\172 Minato tin c\195\180."
L18_1.m_Talk_VTN = L19_1
L19_1 = "\228\189\134\230\152\175\239\188\140\230\136\145\228\191\161\228\187\187\229\179\176\229\165\136\227\128\130\230\137\128\228\187\165\230\137\141\228\188\154\229\184\174\229\138\169\229\179\176\229\165\136\228\191\161\228\187\187\231\154\132\228\189\160\227\128\130"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Aber ich glaube an Minato, und ich werde dir nur helfen, weil Minato an dich glaubt."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mais je crois en Minato. Et si j'accepte de t'aider, c'est seulement parce que lui aussi, il croit en toi."
L18_1.m_Talk_FRA = L19_1
